/**
 * The plumbing below is deliberately untyped against the interface above, and cast
 * once at the end.
 *
 * `send` cannot know an operation's return type — it has a `Response`, not a schema
 * — so every method would otherwise need its own `as` and the file would carry
 * fourteen casts instead of one. The interface is what a caller sees, and it IS
 * derived from the model; this is the seam where a runtime that speaks `unknown`
 * meets it.
 */
type Args = Record<string, unknown>;

const omit = (input: Record<string, unknown>, keys: string[]): Record<string, unknown> => {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(input ?? {})) if (!keys.includes(k)) out[k] = v;
  return out;
};

/** Declared fields become a query string; `undefined` is absent rather than the string "undefined". */
const query = (values: Record<string, unknown> | undefined): string => {
  if (!values) return '';
  const params = new URLSearchParams();
  for (const [k, v] of Object.entries(values)) {
    if (v === undefined || v === null) continue;
    params.set(k, String(v));
  }
  const s = params.toString();
  return s ? `?${s}` : '';
};

export function createClient(options: ClientOptions = {}): HandlebarClient {
  const baseUrl = options.baseUrl ?? '/api';
  const doFetch = options.fetch ?? globalThis.fetch.bind(globalThis);
  const readMessage = options.errorMessage ?? defaultErrorMessage;

  /** One request, against a path that is ALREADY prefixed and query-stringed. */
  const raw = async (fullPath: string, method: string, body: unknown): Promise<Response> => {
    const hasBody = body !== undefined && method !== 'GET' && method !== 'DELETE';
    return await doFetch(fullPath, {
      method,
      headers: {
        ...(hasBody ? { 'content-type': 'application/json' } : {}),
        ...(options.headers?.() ?? {}),
      },
      ...(hasBody ? { body: JSON.stringify(body) } : {}),
    });
  };

  const parse = async (res: Response): Promise<unknown> => {
    const text = await res.text();
    const body: unknown = text ? JSON.parse(text) : null;
    if (!res.ok) throw new ApiError(res.status, readMessage(body, res) ?? res.statusText, body);
    return body;
  };

  const send = async (path: string, method: string, body: unknown, params: unknown): Promise<unknown> =>
    await parse(await raw(`${baseUrl}${path}${query(params as Record<string, unknown>)}`, method, body));

  return {
    closeRepair: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/close`, "POST", omit(input, ["orderId"]), undefined),
    completeRepair: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/complete`, "POST", omit(input, ["orderId"]), undefined),
    createCustomer: (input: Args) =>
      send("/customers", "POST", input, undefined),
    createRepair: (input: Args) =>
      send("/repairs", "POST", input, undefined),
    listCustomers: () =>
      send("/customers", "GET", undefined, undefined),
    portalRepairs: () =>
      send("/portal/repairs", "GET", undefined, undefined),
    priceList: () =>
      send("/prices", "GET", undefined, undefined),
    registerBike: (input: Args) =>
      send(`/customers/${encodeURIComponent(String(input.customerId))}/bikes`, "POST", omit(input, ["customerId"]), undefined),
    startConditionReport: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/condition-report`, "POST", omit(input, ["orderId"]), undefined),
    upsertPrice: (input: Args) =>
      send("/prices", "POST", input, undefined),
    invoicingExport: (input: Args) =>
      send(`/invoicing/${encodeURIComponent(String(input.underlagId))}/export`, "POST", omit(input, ["underlagId"]), undefined),
    invoicingGet: (input: Args) =>
      send(`/invoicing/${encodeURIComponent(String(input.underlagId))}`, "GET", undefined, omit(input, ["underlagId"])),
    invoicingList: (input: Args) =>
      send("/invoicing", "GET", undefined, input),
    protocolCountersign: (input: Args) =>
      send(`/protocols/${encodeURIComponent(String(input.instanceId))}/countersign`, "POST", omit(input, ["instanceId"]), undefined),
    protocolFill: (input: Args) =>
      send(`/protocols/${encodeURIComponent(String(input.instanceId))}/responses`, "POST", omit(input, ["instanceId"]), undefined),
    protocolGet: (input: Args) =>
      send(`/protocols/${encodeURIComponent(String(input.instanceId))}`, "GET", undefined, omit(input, ["instanceId"])),
    protocolListTemplates: () =>
      send("/protocol-templates", "GET", undefined, undefined),
    protocolSign: (input: Args) =>
      send(`/protocols/${encodeURIComponent(String(input.instanceId))}/sign`, "POST", omit(input, ["instanceId"]), undefined),
    protocolVoid: (input: Args) =>
      send(`/protocols/${encodeURIComponent(String(input.instanceId))}/void`, "POST", omit(input, ["instanceId"]), undefined),
    workorderAssign: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/assign`, "POST", omit(input, ["orderId"]), undefined),
    workorderGet: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}`, "GET", undefined, omit(input, ["orderId"])),
    workorderList: (input: Args) =>
      send("/repairs", "GET", undefined, input),
    workorderReportMaterial: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/material`, "POST", omit(input, ["orderId"]), undefined),
    workorderReportTime: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/time`, "POST", omit(input, ["orderId"]), undefined),
    workorderStart: (input: Args) =>
      send(`/repairs/${encodeURIComponent(String(input.orderId))}/start`, "POST", omit(input, ["orderId"]), undefined),
  } as unknown as HandlebarClient;
}
